/* Navigable room atlas. Only interface state is changed; project records stay untouched. */
(()=>{
 'use strict';
 const rooms=[['library','Library','Collect sources you can trace.','Add sources and reading notes'],['reader','Reader','Read a source and capture its exact words.','Open a PDF and capture a passage'],['evidence','Evidence','Compare findings, methods and limitations.','Inspect or compare evidence notes'],['claims','Claims','Connect interpretations to supporting and challenging evidence.','Build an accountable argument'],['synthesis','Synthesis','Explain patterns across your sources.','Code themes and write conclusions'],['design','Research Design','Make each method answer your question.','Align objectives, measures and methods'],['map','Literature Map','Explore the connections you have recorded.','Connect sources in the literature map'],['proposal','Proposal','Bring the research trail into a coherent draft.','Write and revise the proposal'],['review','Review & History','Inspect unresolved prompts and keep a backup.','Review, rehearse and export']];
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const counts=p=>[`${p.papers.length} sources`,`${p.evidence.filter(n=>n.quote).length} passages`,`${p.evidence.length} notes`,`${p.workbench.claims.length} ${p.workbench.claims.length===1?'claim':'claims'}`,`${p.workbench.codes.length} ${p.workbench.codes.length===1?'theme':'themes'}`,`${p.workbench.design.length} ${p.workbench.design.length===1?'objective':'objectives'}`,`${p.edges.length} connections`,`${p.proposal.trim().split(/\s+/).filter(Boolean).length} words`,`${window.REICore.checks(p).length} review prompts`];
 function mount(){const p=window.REIWorkbench?.getProject(),content=document.querySelector('.research-content');if(!p||!content||content.querySelector('.room-compass'))return;const index=rooms.findIndex(r=>r[0]===location.hash.split('/')[2]);if(index<0)return;const count=counts(p),href=i=>'#research/'+esc(p.id)+'/'+rooms[i][0];content.dataset.room=rooms[index][0];
 const compass=document.createElement('div');compass.className='room-compass';compass.innerHTML=`<div class="room-position"><span>${String(index+1).padStart(2,'0')} / 09</span><strong>${esc(rooms[index][1])}</strong></div><div class="room-compass-actions">${index?`<a href="${href(index-1)}" class="text-link" aria-label="Previous room: ${esc(rooms[index-1][1])}">Previous</a>`:''}<button type="button" class="room-atlas-toggle" aria-expanded="false" aria-controls="room-atlas">Room atlas</button>${index<rooms.length-1?`<a href="${href(index+1)}" class="text-link" aria-label="Next room: ${esc(rooms[index+1][1])}">Next: ${esc(rooms[index+1][1])}</a>`:''}</div>`;
 const atlas=document.createElement('section');atlas.className='room-atlas';atlas.id='room-atlas';atlas.hidden=true;atlas.setAttribute('aria-label','Research room atlas');atlas.innerHTML=`<div class="room-atlas-heading"><h3>Your research, connected.</h3><p>Move between rooms as your project develops. Counts describe recorded work, not completion or quality.</p></div><nav class="room-atlas-grid" aria-label="Explore research rooms">${['Gather & inspect','Connect & explain','Develop & review'].map((label,g)=>`<div class="room-atlas-group"><h4>${label}</h4>${rooms.slice(g*3,g*3+3).map((r,j)=>{const i=g*3+j;return `<a href="${href(i)}" data-atlas-room="${i}" ${index===i?'aria-current="page"':''}><span class="atlas-room-index">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(r[1])}</strong><small>${esc(count[i])}</small></span><span class="atlas-room-direction" aria-hidden="true">→</span></a>`}).join('')}</div>`).join('')}</nav><div class="room-atlas-preview"><strong>${esc(rooms[index][3])}</strong><p>${esc(rooms[index][2])}</p></div>`;
 content.prepend(atlas);content.prepend(compass);
 const b=compass.querySelector('button');b.addEventListener('click',()=>{atlas.hidden=!atlas.hidden;b.setAttribute('aria-expanded',String(!atlas.hidden));if(!atlas.hidden){atlas.scrollIntoView({block:'start',behavior:'instant'});const active=atlas.querySelector('[aria-current]');active?.focus({preventScroll:true});if(matchMedia('(max-width:900px)').matches)active?.scrollIntoView({block:'center',behavior:'instant'})}});atlas.addEventListener('keydown',event=>{if(event.key==='Escape'){atlas.hidden=true;b.setAttribute('aria-expanded','false');b.focus()}});const preview=event=>{const a=event.target.closest('[data-atlas-room]');if(!a)return;const r=rooms[Number(a.dataset.atlasRoom)];atlas.querySelector('.room-atlas-preview strong').textContent=r[3];atlas.querySelector('.room-atlas-preview p').textContent=r[2]};atlas.addEventListener('focusin',preview);atlas.addEventListener('pointerover',preview);
 const title=content.querySelector('.research-section-label');if(title){title.querySelector('.eyebrow')?.remove();title.insertAdjacentHTML('beforeend',`<p class="room-task">${esc(rooms[index][3])}<span>${esc(count[index])}</span></p>`)}
 }
 addEventListener('rei:research-render',mount);mount();
})();
